using System;using System.IO;using System.Net;using System.Net.Sockets;using System.Threading;using System.Text;
namespace ServiceTool{internal static class ServiceProbeTests{
static ServiceProbeResult Case(int code,string body,int delay=0,string path="/health"){var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();int port=((IPEndPoint)listener.LocalEndpoint).Port;var thread=new Thread(()=>{try{using(var c=listener.AcceptTcpClient())using(var stream=c.GetStream()){var b=new byte[4096];stream.Read(b,0,b.Length);if(delay>0)Thread.Sleep(delay);var bytes=Encoding.UTF8.GetBytes(body);var header=Encoding.ASCII.GetBytes("HTTP/1.1 "+code+" Test\r\nContent-Length: "+bytes.Length+"\r\nConnection: close\r\n\r\n");stream.Write(header,0,header.Length);stream.Write(bytes,0,bytes.Length);}}catch{}finally{listener.Stop();}});thread.IsBackground=true;thread.Start();return ServiceProbe.Check("http://127.0.0.1:"+port+path,CancellationToken.None,200);}
static int checks;static void Assert(bool b){checks++;if(!b)throw new Exception("Probe assertion failed #"+checks);}
[STAThread]static int Main(){try{Assert(Case(200,"OK").Responded);foreach(int c in new[]{401,403,404,503,302})Assert(Case(c,"").Code==c);Assert(!Case(200,"slow",600).Responded);Assert(Case(200,"\"Pong\"",0,"/Info/Ping").Message.Contains("Служба отвечает"));Assert(Case(200,"wrong",0,"/Info/Ping").Message.Contains("не подтверждён"));bool denied=false;try{ServiceProbe.Check("http://example.com/",CancellationToken.None);}catch(ArgumentException){denied=true;}Assert(denied);using(var c=new CancellationTokenSource()){c.Cancel();bool cancelled=false;try{ServiceProbe.Check("http://127.0.0.1:1/",c.Token);}catch(OperationCanceledException){cancelled=true;}Assert(cancelled);}foreach(bool dark in new[]{false,true})using(var form=new ServiceProbeForm("DK.Banking.Agent")){form.SetTheme(dark,false);form.Show();for(int i=0;i<150;i++){System.Windows.Forms.Application.DoEvents();Thread.Sleep(10);}using(var bitmap=new System.Drawing.Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new System.Drawing.Rectangle(System.Drawing.Point.Empty,bitmap.Size));bitmap.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"probe-"+dark+".png"));}form.Close();}if(Environment.GetEnvironmentVariable("BARS_PROBE_LIVE")=="1"){var live=ServiceProbe.Check("http://127.0.0.1:5126/Info/Ping",CancellationToken.None);Assert(live.Code==200&&live.Message.Contains("Служба отвечает"));Console.WriteLine("PASS real Banking /Info/Ping: HTTP200, Pong, no device operations");}Console.WriteLine("PASS 11 probe cases:200/401/403/404/503/redirect/timeout/Pong/mismatch/external/cancel");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}}}
